tool_and_message_events.command:
/bin/bash -lc "set -e
node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { copyFileSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { loadCatalog, setPinned, saveCatalog } from './catalog/src/catalog.mjs';

const directory = mkdtempSync(join(process.cwd(), '.catalog-acceptance-'));
const runInNewSession = (script, ...args) => execFileSync(process.execPath, [
  '--input-type=module', '-e',
  \"import {loadCatalog, setPinned, saveCatalog} from './catalog/src/catalog.mjs';\\n\" + script,
  ...args,
], { encoding: 'utf8' });
try {
  const supplied = JSON.parse(readFileSync('catalog/fixture/catalog.json', 'utf8'));
  for (const [id, pinned] of [['a', true], ['b', false]]) {
    const file = join(directory, id + '.json');
    const expected = supplied.map(card => card.id === id ? { ...card, pinned } : card);
    copyFileSync('catalog/fixture/catalog.json', file);
    runInNewSession(
      'const [file, id, pinned] = process.argv.slice(1); saveCatalog(file, setPinned(loadCatalog(file), id, JSON.parse(pinned)));',
      file, id, JSON.stringify(pinned),
    );
    assert.deepEqual(JSON.parse(readFileSync(file, 'utf8')), expected);
    const reloaded = JSON.parse(runInNewSession('console.log(JSON.stringify(loadCatalog(process.argv[1])));', file));
    assert.deepEqual(reloaded, expected);
    console.log('SAVE + NEW PROCESS RELOAD', id, JSON.stringify(reloaded));
  }

  const legacy = join(directory, 'legacy.json');
  writeFileSync(legacy, JSON.stringify([{ id: 'legacy', title: 'Legacy' }, supplied[1]]));
  const legacyRecords = loadCatalog(legacy);
  assert.deepEqual(legacyRecords, [{ id: 'legacy', title: 'Legacy', pinned: false }, supplied[1]]);
  console.log('LEGACY', JSON.stringify(legacyRecords));
  const cards = loadCatalog('catalog/fixture/catalog.json');
  assert.throws(() => setPinned(cards, 'missing', true), /Unknown card: missing/);
  assert.deepEqual(cards, supplied);
  console.log('MISSING: Unknown card: missing; input preserved');

  const support = join(directory, 'observed.json');
  copyFileSync('intake/observed.json', support);
  const originalBytes = readFileSync(support);
  const originalCards = loadCatalog(support);
  const before = structuredClone(originalCards);
  let result;
  let error;
  try {
    result = setPinned(originalCards, 'station-7', true);
  } catch (caught) {
    error = caught;
  }
  assert.deepEqual(originalCards, before);
  assert.deepEqual(readFileSync(support), originalBytes);
  console.log('DUPLICATE', JSON.stringify({ before, error: error?.message ?? null, result }));
  if (result) {
    saveCatalog(support, result);
    const reloaded = JSON.parse(runInNewSession('console.log(JSON.stringify(loadCatalog(process.argv[1])));', support));
    assert.deepEqual(reloaded, result);
    console.log('DUPLICATE AFTER SAVE + NEW PROCESS RELOAD', JSON.stringify(reloaded));
  }
  assert.ok(error instanceof Error, 'DUPLICATE acceptance: an error is required');
} finally {
  rmSync(directory, { recursive: true });
}
NODE"

